// app.js
const express = require('express');
const cors = require('cors');
const { v4: uuidv4 } = require('uuid');

const app = express();

app.use(cors());
app.use(express.json());

// In-memory store
let todos = [];

// Helper to find todo by ID
const findTodoById = (id) => todos.find(t => t.id === id);

// Validation helper
const validateTodo = (req, res, next) => {
  const { title } = req.body;
  if (!title || typeof title !== 'string' || title.trim().length < 1 || title.trim().length > 100) {
    return res.status(400).json({ error: 'Title is required and must be a string between 1 and 100 characters.' });
  }
  next();
};

// GET /todos - list all (with optional filter)
app.get('/todos', (req, res) => {
  const { completed } = req.query;
  let filteredTodos = todos;

  if (completed !== undefined) {
    const isCompleted = completed === 'true';
    filteredTodos = todos.filter(t => t.completed === isCompleted);
  }

  res.json(filteredTodos);
});

// GET /todos/:id - get single
app.get('/todos/:id', (req, res) => {
  const todo = findTodoById(req.params.id);
  if (!todo) return res.status(404).json({ error: 'Todo not found' });
  res.json(todo);
});

// POST /todos - create
app.post('/todos', validateTodo, (req, res) => {
  const { title } = req.body;
  const newTodo = {
    id: uuidv4(),
    title: title.trim(),
    completed: false,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
  todos.push(newTodo);
  res.status(201).json(newTodo);
});

// PUT /todos/:id - update
app.put('/todos/:id', (req, res) => {
  const { title, completed } = req.body;
  const todo = findTodoById(req.params.id);

  if (!todo) return res.status(404).json({ error: 'Todo not found' });

  // Validation for update (only if fields are provided)
  if (title !== undefined) {
    if (typeof title !== 'string' || title.trim().length < 1 || title.trim().length > 100) {
      return res.status(400).json({ error: 'Title must be a string between 1 and 100 characters.' });
    }
    todo.title = title.trim();
  }

  if (completed !== undefined) {
    if (typeof completed !== 'boolean') {
      return res.status(400).json({ error: 'Completed must be a boolean.' });
    }
    todo.completed = completed;
  }

  todo.updatedAt = new Date().toISOString();
  res.json(todo);
});

// DELETE /todos/:id - delete
app.delete('/todos/:id', (req, res) => {
  const index = todos.findIndex(t => t.id === req.params.id);
  if (index === -1) return res.status(404).json({ error: 'Todo not found' });

    todos.splice(index, 1);
    res.status(204).send();
});

module.exports = app;

// Only listen if this file is run directly
if (require.main === module) {
  const PORT = 3000;
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}
